"use strict";(()=>{const page=document.body.dataset.page,app=document.getElementById('app');if(!app)return;const $=(s)=>app.querySelector(s),info=(purpose,points,limit)=>{document.getElementById('purpose').textContent=purpose;document.getElementById('points').innerHTML=points.map(x=>`<li>${x}</li>`).join('');document.getElementById('limitation').textContent=limit};const say=s=>document.getElementById('observation').textContent=s;const el=(tag,cl,text)=>{const x=document.createElement(tag);if(cl)x.className=cl;if(text!==undefined)x.textContent=text;return x};const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const runTimer=(button,step,delay=500)=>{let timer=null;const stop=()=>{clearInterval(timer);timer=null;button.textContent='再生'};button.addEventListener('click',()=>{if(timer){stop();return}button.textContent='一時停止';timer=setInterval(()=>{if(step()===false)stop()},delay)});return stop};document.querySelector('.fullscreen')?.addEventListener('click',()=>{const box=document.querySelector('.simulator');if(document.fullscreenElement)document.exitFullscreen();else box.requestFullscreen?.()});function learning(){info('学習の手がかりが違います。教師ありは正解ラベル、教師なしは似た特徴、強化学習は行動後の報酬を使います。',['教師あり：正解付きの例から未知のデータを分類する。','教師なし：正解ラベルなしで似たものをまとめる。','強化学習：報酬を参考に行動方針を改善する。'],'果物は2つの数値だけで表し、教師ありは最近傍分類、教師なしはk-means、強化学習は小さな迷路のQ学習です。実務のモデルはもっと多様です。');app.innerHTML='<div class="controls"><label class="control">学習方法<select id="method"><option value="super">教師あり学習</option><option value="cluster">教師なし学習</option><option value="rl">強化学習</option></select></label></div><div id="scene"></div>';let mode='super';$('#method').onchange=e=>{mode=e.target.value;render()};function render(){const scene=$('#scene');scene.innerHTML='';if(mode==='super')supervised(scene);else if(mode==='cluster')cluster(scene);else reinforce(scene)}
function supervised(scene){let samples=[{x:1,y:2,l:'りんご'},{x:2,y:3,l:'りんご'},{x:6,y:6,l:'みかん'},{x:7,y:5,l:'みかん'}];scene.innerHTML='<p>特徴：横軸は甘さ、縦軸は酸味の模式値。正解ラベル付きの4例から、未知の果物を分類します。</p><div class="controls"><label class="control">甘さ<input id="sx" type="range" min="0" max="8" value="3"></label><label class="control">酸味<input id="sy" type="range" min="0" max="8" value="3"></label><button id="classify">分類する</button></div><div id="lplot"></div><div class="result" id="lout">まだ分類していません。</div>';const plot=$('#lplot');const draw=()=>{let x=+$('#sx').value,y=+$('#sy').value;plot.innerHTML=`<svg class="plot" viewBox="0 0 430 300" role="img" aria-label="果物の特徴分布"><line x1="40" y1="260" x2="400" y2="260" stroke="#789"/><line x1="40" y1="260" x2="40" y2="20" stroke="#789"/><text x="330" y="286">甘さ</text><text x="4" y="24">酸味</text>${samples.map(p=>`<circle cx="${40+p.x*42}"cy="${260-p.y*28}"r="13"fill="${p.l==='りんご'?'#e678a0':'#4ba8ce'}"/><text x="${52+p.x*42}"y="${263-p.y*28}"font-size="13">${p.l}</text>`).join('')}<circle cx="${40+x*42}" cy="${260-y*28}" r="15" fill="#fff" stroke="#183044" stroke-width="3"/></svg>`};draw();$('#sx').oninput=draw;$('#sy').oninput=draw;$('#classify').onclick=()=>{const x=+$('#sx').value,y=+$('#sy').value;const near=samples.map(p=>({...p,d:Math.hypot(x-p.x,y-p.y)})).sort((a,b)=>a.d-b.d)[0];$('#lout').textContent=`最も近い正解付きデータは「${near.l}」（距離 ${near.d.toFixed(2)}）。この簡易分類器は「${near.l}」と予測します。`;say('入力した特徴と、ラベル付きの例との距離が変わると、分類結果も変わります。正解ラベルが学習の手がかりです。')};say('教師あり学習では、正解ラベル付きの例を使って未知の入力を分類します。')}
function cluster(scene){let pts=[[1,2],[2,1],[2,3],[6,6],[7,5],[6,4]];scene.innerHTML='<p>ラベルはありません。点を追加し、2つの中心へ繰り返し割り当てる様子を見ます。</p><div class="controls"><label class="control">特徴A<input id="cx" type="range" min="0" max="8" value="4"></label><label class="control">特徴B<input id="cy" type="range" min="0" max="8" value="4"></label><button id="add">データを追加</button><button id="iterate" class="secondary">1ステップ進む</button><button id="reset" class="secondary">リセット</button></div><div id="cplot"></div><div id="cout" class="result"></div>';let centers=[[1,1],[7,7]],assign=[],step=0;function draw(){assign=pts.map(p=>Math.hypot(p[0]-centers[0][0],p[1]-centers[0][1])<=Math.hypot(p[0]-centers[1][0],p[1]-centers[1][1])?0:1);$('#cplot').innerHTML=`<svg class="plot" viewBox="0 0 420 310" role="img" aria-label="グループ分けの位置図">${pts.map((p,i)=>`<circle cx="${40+p[0]*43}"cy="${265-p[1]*29}"r="13"fill="${assign[i]?'#e78bac':'#39a3ca'}"/>`).join('')}${centers.map((p,i)=>`<text x="${35+p[0]*43}"y="${270-p[1]*29}"font-size="25"font-weight="bold">×</text>`).join('')}<text x="15" y="298">× はグループの中心</text></svg>`;$('#cout').textContent=`${pts.length}件のデータ、中心の更新 ${step}回。水色 ${assign.filter(v=>v===0).length}件、ピンク ${assign.filter(v=>v===1).length}件。`};$('#add').onclick=()=>{pts.push([+$('#cx').value,+$('#cy').value]);draw();say('新しいデータを追加すると、中心への近さによって所属グループが決まります。次に中心を更新して違いを見てください。')};$('#iterate').onclick=()=>{for(let k=0;k<2;k++){const group=pts.filter((_,i)=>assign[i]===k);if(group.length)centers[k]=[group.reduce((a,p)=>a+p[0],0)/group.length,group.reduce((a,p)=>a+p[1],0)/group.length]}step++;draw();say('割り当てられた点の平均位置へ中心が動きました。正解ラベルを教えずに、似た位置の点をまとめています。')};$('#reset').onclick=()=>{pts=[[1,2],[2,1],[2,3],[6,6],[7,5],[6,4]];centers=[[1,1],[7,7]];step=0;draw()};draw()}
function reinforce(scene){scene.innerHTML='<p>赤い枠のエージェントが左下から右上のゴールを目指します。ゴールは +10、1移動は −1。試行ごとに行動価値を更新します。</p><div class="controls"><button id="episode">1試行進む</button><button id="play" class="secondary">再生</button><button id="reset" class="secondary">リセット</button></div><div class="compare"><div class="panel"><p class="panel-title">迷路</p><div class="grid-board" id="maze"></div></div><div class="panel"><p class="panel-title">試行結果</p><div id="rout"></div></div></div>';const walls=new Set([5,6,9,12]),goal=3,Q=Array.from({length:16},()=>[0,0,0,0]);let episodes=0,last=0,agent=12;const moves=[-4,1,4,-1],valid=(s,a)=>{const n=s+moves[a];return n>=0&&n<16&&!walls.has(n)&&!(a===1&&s%4===3)&&!(a===3&&s%4===0)};let seed=7391;const random=()=>{seed=(seed*16807)%2147483647;return seed/2147483647};function draw(){const board=$('#maze');board.style.gridTemplateColumns='repeat(4,1fr)';board.innerHTML=Array.from({length:16},(_,i)=>`<div class="cell ${walls.has(i)?'wall':''} ${i===goal?'goal':''} ${i===agent?'agent':''}">${i===goal?'ゴール':i===agent?'現在地':''}</div>`).join('');$('#rout').textContent=`試行 ${episodes}回。直近は ${last}歩で終了。行動価値は報酬を受けるたびに更新されます。`};function episode(){let s=12,steps=0;while(s!==goal&&steps<70){const choices=[0,1,2,3].filter(a=>valid(s,a));const explore=random()<Math.max(.08,.65-episodes*.015);const max=Math.max(...choices.map(a=>Q[s][a]));const a=explore?choices[Math.floor(random()*choices.length)]:choices.find(a=>Q[s][a]===max);const n=s+moves[a],reward=n===goal?10:-1;Q[s][a]+=.35*(reward+.9*Math.max(...Q[n])-Q[s][a]);s=n;steps++}agent=s;episodes++;last=steps;draw();say(`報酬を使って行動価値を更新しました。${episodes}回目は${steps}歩。探索があるため歩数は毎回必ず減るわけではありません。`);return episodes<80}const stop=runTimer($('#play'),episode,300);$('#episode').onclick=episode;$('#reset').onclick=()=>{stop();Q.forEach(row=>row.fill(0));episodes=0;last=0;agent=12;seed=7391;draw();say('報酬から学んだ行動価値をリセットしました。')};draw()}
render();}
function cnn(){info('CNNは小さなフィルターを画像上で動かし、局所的な線や模様への反応を特徴マップにします。さらに多層の処理と学習済みの重みを使って分類します。',['フィルターの位置が変わると反応値も変わる。','縦線用と横線用のフィルターでは強く反応する場所が違う。','特徴マップだけでは数字の正解が決まらず、後段の学習済み分類器が必要。'],'画素と畳み込みの計算は実行します。最後の数字候補は特徴量を比べる手作りの模式スコアで、学習済みCNNの推論結果ではありません。');const digits={'1':['0011000','0111000','0011000','0011000','0011000','0011000','0111100'],'7':['1111100','0001100','0011000','0011000','0110000','0110000','0110000'],'0':['0111100','1100110','1100110','1100110','1100110','1100110','0111100']};const filters={vertical:[[1,0,-1],[1,0,-1],[1,0,-1]],horizontal:[[1,1,1],[0,0,0],[-1,-1,-1]]};let digit='1',filter='vertical',position=0;app.innerHTML='<div class="controls"><label class="control">入力数字<select id="digit"><option>1</option><option>7</option><option>0</option></select></label><label class="control">フィルター<select id="filter"><option value="vertical">縦線</option><option value="horizontal">横線</option></select></label><button id="step">1ステップ進む</button><button id="play" class="secondary">再生</button><button id="reset" class="secondary">リセット</button></div><div class="three"><div class="panel"><p class="panel-title">1 入力画像（7×7）</p><div id="pixels" class="pixel-board"></div></div><div class="panel"><p class="panel-title">2 フィルター（3×3）</p><div id="kernel" class="matrix"></div><p>明るい画素と重なる値を掛け、合計します。</p></div><div class="panel"><p class="panel-title">3 特徴マップ（5×5）</p><div id="feature" class="pixel-board" style="grid-template-columns:repeat(5,1fr)"></div></div></div><div class="result" id="cnn-result"></div>';const matrix=()=>digits[digit].map(row=>[...row].map(Number));function conv(m,k){return Array.from({length:5},(_,y)=>Array.from({length:5},(_,x)=>Math.max(0,k.reduce((sum,r,dy)=>sum+r.reduce((v,w,dx)=>v+w*m[y+dy][x+dx],0),0))))}function draw(){const m=matrix(),k=filters[filter],f=conv(m,k),x=position%5,y=Math.floor(position/5);$('#pixels').innerHTML=m.flatMap((row,yy)=>row.map((v,xx)=>`<span class="pixel" style="background:${v?'#287fac':'#e7f0f5'};outline:${xx>=x&&xx<x+3&&yy>=y&&yy<y+3?'2px solid #ef74a4':'none'}"></span>`)).join('');$('#kernel').innerHTML=k.flat().map(v=>`<span>${v}</span>`).join('');$('#feature').innerHTML=f.flat().map((v,i)=>`<span class="pixel" style="background:rgba(32,150,196,${Math.min(v/4,.95)});outline:${i===position?'2px solid #ef74a4':'none'}" title="反応 ${v}"></span>`).join('');const vertical=conv(m,filters.vertical).flat().reduce((a,b)=>a+b,0),horizontal=conv(m,filters.horizontal).flat().reduce((a,b)=>a+b,0);$('#cnn-result').textContent=`位置 (${x+1}, ${y+1}) の反応値：${f[y][x]}。縦線の反応合計 ${vertical}、横線の反応合計 ${horizontal}。模式的な分類候補：${vertical>horizontal*1.45?'1':horizontal>vertical*1.2?'7':'0 / 7'}。この候補は学習済みCNNの判定ではありません。`};const stop=runTimer($('#play'),()=>{if(position===24)return false;position++;draw();say('フィルターを1画素ずつ移動すると反応位置が変わります。線の向きによって特徴マップも変わります。');return true},160);$('#digit').onchange=e=>{digit=e.target.value;position=0;stop();draw()};$('#filter').onchange=e=>{filter=e.target.value;position=0;stop();draw();say('同じ画像でも、縦線と横線のフィルターでは反応する場所が変わります。')};$('#step').onclick=()=>{position=(position+1)%25;draw()};$('#reset').onclick=()=>{stop();position=0;draw()};draw();}
function token(){info('文章を、モデルが扱う小さな単位（トークン）に分けて、それぞれを数値IDに対応付けます。実際の分け方はモデルの語彙に依存します。',['文字数とトークン数は一致しない。','同じ文字列でも、分割方法が違うとトークン数が変わる。','IDは語彙表の番号であり、単語の意味そのものを表す値ではない。'],'このページは学習用の簡易分割です。実際のトークナイザーやモデルのトークンIDではありません。日本語の形態素解析も行いません。');app.innerHTML='<label class="control">文章を入力<textarea id="sentence">今日はよい天気です。 AI is useful!</textarea></label><div class="controls"><label class="control">分割例<select id="strategy"><option value="word">語・記号のまとまり</option><option value="char">1文字ずつ</option></select></label><button id="split">分割する</button></div><div class="compare"><div class="panel"><p class="panel-title">分割されたトークンとID</p><div id="tokens" class="chips"></div></div><div class="panel"><p class="panel-title">数を比較</p><div id="counts"></div></div></div>';const vocab=new Map();function split(){const text=$('#sentence').value;const strategy=$('#strategy').value;const tokens=strategy==='char'?[...text]:text.match(/[一-龯々]+|[ぁ-ん]+|[ァ-ヴー]+|[A-Za-z]+|[0-9]+|\s+|[^\s]/g)||[];const box=$('#tokens');box.replaceChildren();for(const t of tokens){if(!vocab.has(t))vocab.set(t,1000+vocab.size);const item=el('span','token-item'),chip=el('span','chip',t===' '?'空白':t),id=el('small','',`ID ${vocab.get(t)}`);item.append(chip,id);box.append(item)}$('#counts').textContent=`文字数：${[...text].length}文字 ／ トークン数：${tokens.length}個。空白も分割対象です。`;say(`${strategy==='char'?'1文字単位':'語・記号のまとまり'}では ${tokens.length} トークン。分割方法を変えると同じ文章でも数が変わります。`)}$('#split').onclick=split;$('#strategy').onchange=split;split();}
function prediction(){info('言語モデルは、それまでのトークンを手がかりに次のトークンの確率分布を作り、1つを選んで文脈に追加する操作を繰り返します。',['Temperatureを下げると高確率の候補に集中し、上げると分布が平らになる。','候補を1つ選ぶたびに文脈が増え、次の候補が変わる。','確率が高くても事実として正しいとは限らない。'],'候補と基準確率は手作りの例です。Temperatureの再計算は実際に行いますが、LLMは動かしていません。');const states=[{context:'今日の天気は',opts:[['晴れ',.58],['雨',.27],['くもり',.12],['雪',.03]]},{context:'',opts:[['です。',.65],['でしょう。',.2],['かもしれません。',.1],['！',.05]]},{context:'',opts:[['散歩に行きましょう。',.48],['傘を持ちましょう。',.25],['外を見てみましょう。',.2],['',.07]]}];let chosen=[];app.innerHTML='<div class="controls"><label class="control">Temperature <output id="temp-value">1.0</output><input type="range" id="temp" min="0.2" max="2" step="0.1" value="1"></label><button id="reset" class="secondary">リセット</button></div><div class="compare"><div class="panel"><p class="panel-title">現在の文章</p><p id="context"></p></div><div class="panel"><p class="panel-title">低温と高温の比較</p><div id="temp-compare"></div></div></div><div class="panel"><p class="panel-title">次の候補（選ぶと続きます）</p><div id="options"></div></div>';function probs(opts,t){const z=opts.map(([,p])=>Math.pow(p,1/t)),sum=z.reduce((a,b)=>a+b,0);return z.map(v=>v/sum)}function bars(opts,p,clickable){return opts.map(([word],i)=>`<div class="bar-row"><span>${safe(word||'終了')}</span><div class="bar-track"><div class="bar-fill" style="width:${(p[i]*100).toFixed(1)}%"></div></div>${clickable?`<button type="button"data-choose="${i}"aria-label="${safe(word||'終了')}を選ぶ">${Math.round(p[i]*100)}%</button>`:`<span>${Math.round(p[i]*100)}%</span>`}</div>`).join('')}function draw(){const step=Math.min(chosen.length,2),opts=states[step].opts,t=+$('#temp').value;$('#temp-value').textContent=t.toFixed(1);$('#context').textContent=states[0].context+chosen.join('');$('#options').innerHTML=chosen.length>=3?'<p>文が完成しました。リセットして条件を変えてください。</p>':bars(opts,probs(opts,t),true);$('#temp-compare').innerHTML='<p>Temperature 0.3</p>'+bars(opts,probs(opts,.3),false)+'<p>Temperature 1.8</p>'+bars(opts,probs(opts,1.8),false);$('#options').querySelectorAll('[data-choose]').forEach(b=>b.onclick=()=>{chosen.push(opts[+b.dataset.choose][0]);draw();say(`1トークンを選び、文脈に追加しました。現在 ${chosen.length} ステップ。次の確率は新しい文脈を使う想定です。`)});say(`Temperature ${t.toFixed(1)}。低いほど最上位候補へ確率が集まる様子を、左右の比較と見比べてください。`)}$('#temp').oninput=draw;$('#reset').onclick=()=>{chosen=[];draw()};draw();}
function attention(){info('Self-Attentionは、ある語を処理するときに文中のほかの語をどの程度参照するかを計算し、情報を集めます。',['遠く離れた語も直接参照できる。','Queryは「何を探すか」、Keyは「何に関する情報か」、Valueは「取り出す情報」の役割。','Attentionの大きさだけでモデルの判断理由を断定できない。'],'線の強さは手作りの模式例です。実際のAttentionの重みやモデルの解釈結果ではありません。');const words=['花子は','図書館で','本を','借りた。','それを','家で','読んだ。'];const weights=[[1,.1,.12,.18,.07,.05,.06],[.1,1,.2,.3,.08,.05,.04],[.2,.14,1,.55,.75,.1,.28],[.1,.25,.45,1,.22,.08,.32],[.08,.05,.85,.18,1,.1,.55],[.05,.08,.08,.1,.12,1,.35],[.08,.06,.5,.3,.65,.35,1]];let selected=4;app.innerHTML='<p>「それを」を選び、離れた「本を」との関係を確かめてください。</p><div id="attention-words" class="controls"></div><div class="svg-wrap"><svg id="attention-svg" class="plot" viewBox="0 0 760 250" role="img" aria-label="単語間の注目度"></svg></div><div class="result" id="attention-out"></div>';function draw(){const wrap=$('#attention-words');wrap.replaceChildren();words.forEach((w,i)=>{const b=el('button',i===selected?'pink':'secondary',w);b.onclick=()=>{selected=i;draw()};wrap.append(b)});const svg=$('#attention-svg'),x=i=>50+i*110;svg.innerHTML=words.map((w,i)=>`<path d="M${x(selected)} 180 Q${(x(selected)+x(i))/2} ${15+Math.abs(selected-i)*4} ${x(i)} 180" fill="none" stroke="${i===selected?'#dd5f91':'#258ab6'}" stroke-width="${Math.max(1,weights[selected][i]*11)}" opacity="${Math.max(.22,weights[selected][i])}"/>`).join('')+words.map((w,i)=>`<text x="${x(i)}" y="215" text-anchor="middle" font-size="17">${w}</text>`).join('');const top=weights[selected].map((v,i)=>({v,i})).filter(x=>x.i!==selected).sort((a,b)=>b.v-a.v)[0];$('#attention-out').textContent=`「${words[selected]}」から最も強く参照する模式例は「${words[top.i]}」（注目度 ${top.v.toFixed(2)}）。Query＝今の語が探す情報、Key＝各語の見出し、Value＝取り出す内容、と考えます。`;say(`「${words[selected]}」を選ぶと線の太さが変わりました。離れた位置の語にもつながれます。`)}draw();}
function embedding(){info('埋め込みは言葉などを数値のベクトルに変換します。ベクトル同士の向きや距離を使って近い候補を探せます。',['似た意味の言葉が近い方向に置かれることがある。','コサイン類似度は2つのベクトルの向きの近さを −1〜1 で表す。','2次元図では多次元の意味を完全には表せない。'],'座標は説明用に手作りした2次元の模式値で、実際の埋め込みモデルによる学習結果ではありません。');const words=[['犬',2,6],['猫',2.8,6.5],['馬',3.4,5.7],['りんご',7,6.8],['みかん',7.8,6.2],['バナナ',7,7.8],['電車',6,2.2],['バス',6.8,2.7],['自転車',5.8,3]];let current=0;app.innerHTML='<div class="controls"><label class="control">検索する言葉<select id="query"></select></label></div><div class="compare"><div class="panel"><p class="panel-title">2次元の模式図</p><svg id="vector-plot" class="plot" viewBox="0 0 500 400" role="img" aria-label="言葉の座標"></svg></div><div class="panel"><p class="panel-title">コサイン類似度による順位</p><div id="neighbors"></div><p class="small">類似度 = 内積 ÷（2つの長さの積）。原点からの向きの近さを比べます。</p></div></div>';$('#query').innerHTML=words.map((w,i)=>`<option value="${i}">${w[0]}</option>`).join('');function similarity(a,b){const dot=a[1]*b[1]+a[2]*b[2];return dot/(Math.hypot(a[1],a[2])*Math.hypot(b[1],b[2]))}function draw(){const q=words[current],x=w=>35+w[1]*52,y=w=>365-w[2]*42;$('#vector-plot').innerHTML=`<line x1="35" y1="365" x2="480" y2="365" stroke="#789"/><line x1="35" y1="365" x2="35" y2="20" stroke="#789"/><line x1="35" y1="365" x2="${x(q)}" y2="${y(q)}" stroke="#db6f9c" stroke-width="3"/>`+words.map((w,i)=>`<circle cx="${x(w)}" cy="${y(w)}" r="${i===current?13:9}" fill="${i===current?'#db6f9c':'#258eb8'}"/><text x="${x(w)+11}" y="${y(w)-9}" font-size="15">${w[0]}</text>`).join('');const order=words.map((w,i)=>({name:w[0],i,score:similarity(q,w)})).filter(v=>v.i!==current).sort((a,b)=>b.score-a.score);$('#neighbors').innerHTML=order.slice(0,5).map((v,i)=>`<div class="bar-row"><span>${i+1}. ${v.name}</span><div class="bar-track"><div class="bar-fill" style="width:${v.score*100}%"></div></div><span>${v.score.toFixed(2)}</span></div>`).join('');say(`「${q[0]}」のコサイン類似度上位は「${order[0].name}」。座標の向きを比較した結果です。`)}$('#query').onchange=e=>{current=+e.target.value;draw()};draw();}
function rag(){info('RAGは質問に関係する外部文書を検索し、取得した内容を参考情報として生成モデルへ渡す方法です。',['チャンクサイズが変わると検索単位が変わる。','取得した根拠を確認すると回答の検証がしやすい。','検索漏れや古い文書、生成時の誤読があるとRAGでも誤答する。'],'検索は語句の一致による簡易スコアです。回答文は取得文を組み合わせるテンプレートで、LLM・ベクトル検索は使っていません。');const docs=['施設案内。図書室は平日9時から18時まで利用できます。土曜は10時から16時です。日曜と祝日は休室です。','貸出規程。図書は一人3冊まで、14日間借りられます。延長は一度だけ7日間可能です。','施設案内。会議室は平日9時から20時まで利用できます。予約は前日までに窓口で申し込んでください。'];const questions=[['図書室は土曜日に何時まで使えますか？',['図書室','土曜'],'16時'],['本は何冊まで借りられますか？',['図書','冊'],'3冊'],['会議室はいつまでに予約しますか？',['会議室','予約'],'前日まで']];let size=40,qi=0;app.innerHTML='<div class="controls"><label class="control">チャンクサイズ <output id="chunk-value">40</output>文字<input id="size" type="range" min="20" max="90" step="10" value="40"></label><label class="control">質問<select id="question"></select></label><button id="retrieve">検索して回答する</button></div><div class="step-list"><span>1 文書を分割</span><span>2 検索・取得</span><span>3 回答を作成</span></div><div class="compare"><div class="panel"><p class="panel-title">架空の文書とチャンク</p><div id="chunks"></div></div><div class="panel"><p class="panel-title">回答を比較</p><div id="answers"></div></div></div>';$('#question').innerHTML=questions.map((q,i)=>`<option value="${i}">${q[0]}</option>`).join('');function chunks(){return docs.flatMap((d,di)=>{const parts=[];for(let i=0;i<d.length;i+=size)parts.push({text:d.slice(i,i+size),di,index:i});return parts})}function render(hit=-1){const parts=chunks();$('#chunk-value').textContent=size;$('#chunks').innerHTML=parts.map((p,i)=>`<div class="chunk ${i===hit?'hit':''}"><span class="small">文書${p.di+1}・${p.index+1}文字目から</span><br>${safe(p.text)}</div>`).join('');return parts}$('#size').oninput=e=>{size=+e.target.value;render();$('#answers').textContent='チャンクサイズを変えました。もう一度検索してください。';say('チャンクサイズを変えると、文がどこで区切られるか変わります。')};$('#question').onchange=e=>{qi=+e.target.value;render();$('#answers').textContent='質問を選び、検索してください。'};$('#retrieve').onclick=()=>{const q=questions[qi],parts=chunks(),scores=parts.map(p=>q[1].reduce((n,k,i)=>n+(p.text.includes(k)?(i===0?1:3):0),0));const best=Math.max(...scores),hit=scores.indexOf(best);render(hit);const found=best>0?parts[hit]:null,grounded=found&&found.text.includes(q[2]);$('#answers').innerHTML=`<p><strong>RAGなしの模式例</strong><br>「確認できる資料がないため、利用案内を確認してください。」</p><p><strong>検索したチャンク</strong><br>${found?safe(found.text):'該当なし'}</p><p><strong>RAGありの回答例</strong><br>${grounded?`取得した「${safe(found.text)}」を根拠に、答えは「${q[2]}」です。`:'取得した部分だけでは答えを確認できません。元文書やほかのチャンクを調べてください。'}</p>`;say(grounded?'取得したチャンクに答えが含まれていました。根拠を確認してから回答を利用してください。':'必要な文がチャンクの境目で切れたか、検索で見つからなかった可能性があります。RAGでも必ず正しく答えられるわけではありません。')};render();$('#answers').textContent='質問とチャンクサイズを選び、検索してください。';}
function diffusion(){info('学習時は画像に段階的にノイズを加え、どのノイズを除くか予測するモデルを学習します。生成時は新しいノイズから、学習済みモデルの予測を使って画像を作ります。',['学習の前向き過程では画像の情報が徐々に見えなくなる。','生成の逆向き過程は新しいノイズを出発点にする。','生成は元画像をそのまま復元する処理ではない。'],'ここではノイズ加算を実計算し、生成側は固定の目標図形へ近づける模式計算です。学習済み拡散モデルは使っていません。');let stage=0,direction='forward';const source=Array.from({length:16},(_,y)=>Array.from({length:16},(_,x)=>{const dx=x-7.5,dy=y-7.5;return dx*dx+dy*dy<35?40:230}));let seed=613;const rng=()=>{seed=(seed*16807)%2147483647;return seed/2147483647};const noise=Array.from({length:16},()=>Array.from({length:16},()=>Math.round(rng()*255)));const target=Array.from({length:16},(_,y)=>Array.from({length:16},(_,x)=>Math.abs(x-y)<2?50:230));app.innerHTML='<div class="controls"><label class="control">過程<select id="direction"><option value="forward">学習時：ノイズを加える</option><option value="reverse">生成時：ノイズから作る</option></select></label><label class="control">段階 <output id="stage-value">0</output> / 10<input id="stage" type="range" min="0" max="10" value="0"></label><button id="step">1ステップ進む</button><button id="play" class="secondary">再生</button><button id="reset" class="secondary">リセット</button></div><div class="compare"><div class="panel"><p class="panel-title" id="start-label">出発点</p><canvas id="start-canvas" width="256" height="256" class="plot"></canvas></div><div class="panel"><p class="panel-title">現在の段階</p><canvas id="current-canvas" width="256" height="256" class="plot"></canvas></div></div><div id="diff-result" class="result"></div>';function paint(canvas,data){const ctx=canvas.getContext('2d'),img=ctx.createImageData(256,256);for(let y=0;y<256;y++)for(let x=0;x<256;x++){const v=data[Math.floor(y/16)][Math.floor(x/16)],i=(y*256+x)*4;img.data[i]=v;img.data[i+1]=v;img.data[i+2]=v;img.data[i+3]=255}ctx.putImageData(img,0,0)}function draw(){const t=stage/10,forward=direction==='forward',start=forward?source:noise;const current=start.map((row,y)=>row.map((v,x)=>Math.round(forward?(1-t)*v+t*noise[y][x]:(1-t)*v+t*target[y][x])));paint($('#start-canvas'),start);paint($('#current-canvas'),current);$('#start-label').textContent=forward?'元画像（学習用の例）':'新しく用意したノイズ';$('#stage').value=stage;$('#stage-value').textContent=stage;$('#diff-result').textContent=forward?`ノイズを加える段階 ${stage}/10。元画像の画素と固定ノイズを混合しています。`:`ノイズから生成する模式段階 ${stage}/10。元画像とは異なる線の図形へ近づく例です。`;say(forward?'学習時の前向き過程では、段階が進むほど元画像の情報が隠れます。':'生成時は新しいノイズから始めます。ここでは模式的な図形へ近づけ、元画像の単純な復元ではないことを示します。')}const stop=runTimer($('#play'),()=>{if(stage>=10)return false;stage++;draw();return true},300);$('#direction').onchange=e=>{stop();direction=e.target.value;stage=0;draw()};$('#stage').oninput=e=>{stop();stage=+e.target.value;draw()};$('#step').onclick=()=>{stage=Math.min(10,stage+1);draw()};$('#reset').onclick=()=>{stop();stage=0;draw()};draw();}
({learning,cnn,token,prediction,attention,embedding,rag,diffusion})[page]?.();})();